/**
 * Continuation kinds and event lists registered at runtime. A channel
 * module registers its kind when it loads. The public union does not
 * grow for a new kind.
 */
const continuations = new Map();
export function registerContinuation(registration) {
    if (continuations.has(registration.type)) {
        return;
    }
    continuations.set(registration.type, registration);
}
export function continuationForType(type) {
    return continuations.get(type);
}
const eventTypesByMeta = new WeakMap();
export function registerContinuationEventTypes(meta, eventTypes) {
    eventTypesByMeta.set(meta, eventTypes);
}
export function continuationEventTypesFor(meta) {
    if (meta === undefined) {
        return undefined;
    }
    return eventTypesByMeta.get(meta);
}
const channelPacks = [];
export function registerContinuationChannel(pack) {
    if (channelPacks.some((existing) => existing.kind === pack.kind)) {
        return;
    }
    channelPacks.push(pack);
}
export function registeredContinuationChannels() {
    return channelPacks;
}
